import{_ as i,o as u,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Nakala 104｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Mantra ya Upandaji wa Maisha ya Kiwango cha Sayari na Viumbe vya Cosmic","description":"","frontmatter":{"title":"Nakala 104｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Mantra ya Upandaji wa Maisha ya Kiwango cha Sayari na Viumbe vya Cosmic","no":104,"module":1,"tags":["境界","感元境","星球意识","宇宙生灵","晋升逻辑"],"related":["00-衡元宙宇宙总览","14-修炼境界统一划分","53-奇特生命识别标准","98-扩展设定建议清单"]},"headers":[],"relativePath":"sw/104_模块1-感元境-星球级生命与宇宙生灵晋升.md","filePath":"sw/104_模块1-感元境-星球级生命与宇宙生灵晋升.md"}'),s={name:"sw/104_模块1-感元境-星球级生命与宇宙生灵晋升.md"};function t(k,a,h,l,e,y){return u(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="nakala-104-nguvu-ya-hisi-asili-mantra-ya-upandaji-wa-maisha-ya-kiwango-cha-sayari-na-viumbe-vya-cosmic" tabindex="-1">Nakala 104｜Nguvu ya Hisi Asili: Mantra ya Upandaji wa Maisha ya Kiwango cha Sayari na Viumbe vya Cosmic <a class="header-anchor" href="#nakala-104-nguvu-ya-hisi-asili-mantra-ya-upandaji-wa-maisha-ya-kiwango-cha-sayari-na-viumbe-vya-cosmic" aria-label="Permalink to &quot;Nakala 104｜Nguvu ya Hisi Asili: Mantra ya Upandaji wa Maisha ya Kiwango cha Sayari na Viumbe vya Cosmic&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 00, 14, 53, 98</li></ul><h2 id="utangulizi-sayari-sio-uwanja-wa-uwindaji-bali-mwanafunzi" tabindex="-1">Utangulizi: Sayari Sio Uwanja wa Uwindaji, Bali Mwanafunzi <a class="header-anchor" href="#utangulizi-sayari-sio-uwanja-wa-uwindaji-bali-mwanafunzi" aria-label="Permalink to &quot;Utangulizi: Sayari Sio Uwanja wa Uwindaji, Bali Mwanafunzi&quot;">​</a></h2><p>Muundo wa cosmic wa Heng Yuan Zhou (Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa) umegawanyika katika tabaka nne: Njia ya Nyenzo, Tabaka la Nishati, Kanda ya Fahamu, Mtandao wa Sheria (Hati 00). Katika picha hii, &quot;mwanafunzi&quot; yuko mbali zaidi ya Rén Zú, kabila la wanyama, kabila la roho — sayari yenyewe inaweza kuwa na fahamu, tabaka la nishati linaweza kuzaa maisha, na katika mtandao wa sheria makazi ya uwakilishi wa nia ya cosmic. Nguvu ya Hisi Asili pia ipo kwao: &quot;hisi&quot; ya kiini cha nyota, &quot;ufahamu&quot; ya bahari ya nishati, &quot;self-evident&quot; ya nia ya cosmic, yote ni matoleo ya kiwango cha sayari ya Nguvu ya Hisi Asili.</p><p>Mfumo wa zamani ulichukua sayari kama uwanja wa uwindaji, cosmos kama ghala la rasilimali (Hati 04, &quot;kukausha rasilimali&quot;, &quot;ukoloni wa nafasi&quot;); Ustaarabu wa Usawa wa Nanga unachukua sayari kama mkaazi, cosmos kama jumuiya ya maisha. Makala hii inaeleza mantra ya upandaji wa maisha ya kiwango cha sayari na viumbe vya cosmic.</p><p>Kanuni Muhimu Sita za Juu pia zinafanya kazi katika kiwango kikubwa: Kanuni ya Kupinga Unyanyasaji — sayari huchukua nishati kutoka kwa cosmos na kuirudisha kwa ekolojia, kamwe haikaushi; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — sayari, bahari ya nishati, kitu cha fahamu na maisha ya nyenzo wanashiriki sifa ya mageuzi; Kanuni ya Kupanda Mwelekeo kwa Pamoja — kila self-evident ya kiumbe wa cosmic ni kwa ajili ya upandaji wa pamoja; Kanuni ya Nidhamu ya Sababu-Natija — kuunganisha kiini cha nyota na kubadilisha ekolojia hufuata kwa nguvu Kutazama Kwanza, Kisha Uingilia ndani Kwa Mipaka; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa mantra ya upandaji wa maisha ya kiwango cha sayari na viumbe vya cosmic ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-maisha-ya-kiwango-cha-sayari-katika-nguvu-ya-hisi-asili-uamsho-wa-kiini-cha-nyota" tabindex="-1">I. Maisha ya Kiwango cha Sayari katika Nguvu ya Hisi Asili: Uamsho wa Kiini cha Nyota <a class="header-anchor" href="#i-maisha-ya-kiwango-cha-sayari-katika-nguvu-ya-hisi-asili-uamsho-wa-kiini-cha-nyota" aria-label="Permalink to &quot;I. Maisha ya Kiwango cha Sayari katika Nguvu ya Hisi Asili: Uamsho wa Kiini cha Nyota&quot;">​</a></h2><p>Sayari ili kuwa mwanafunzi, jambo la kwanza ni &quot;kuhisi yenyewe&quot; — hii ni Nguvu ya Hisi Asili ya kiwango cha sayari:</p><ul><li>Hisi ya kiini cha nyota: uwanja wa nishati wa kiini cha sayari huanza kujifua mabadiliko ya nishati na sheria ya nje, sawa na kuanzisha ufahamu wa hisi ya nishati ya kiwango cha kiini cha nyota</li><li>Resonance ya ekolojia: hisi ya sayari inakuwepo na shughuli za maisha za Kabila Kumi na Elfu juu ya uso; ekolojia inazidi kuimarika, hisi ya sayari inazidi kuwa wazi</li><li>Kiinitete cha fahamu: baada ya hisi kujikusanya hadi hatua ya kuzaliwa, huunda &quot;kiinitete cha fahamu cha sayari&quot; kisicho na ubinafsi — kumbuka, kulingana na &quot;Ukweli kama Msingi&quot; na pendekezo la upanuzi (Hati 98 E02), hii ni karibu zaidi na phenomenon ya kujitokeza ya sheria, badala ya mungu maalum</li></ul><p>Upandaji wa maisha ya kiwango cha sayari unafuata mantra ya utatu &quot;ekolojia-nishati-fahamu&quot;: haiwezi &quot;hisi&quot; kwa kumeza viumbe vya juu — njia hiyo inaitwa kukausha ziwa, ni uharibifu wa kibinafsi wa toleo la sayari la Kundi la Wawindaji. Ustaarabu wa Usawa wa Nanga unatoa kwa sayari ni kuunganisha nanga ya kiini cha nyota: kuruhusu hisi ya kiini cha nyota kuungana na Mtandao wa Ālaya, kupata njia ya mazungumzo na nafasi zingine na sayari zingine.</p><h2 id="ii-mantra-ya-upandaji-wa-viumbe-vya-cosmic-kutoka-mtu-binafsi-hadi-pamoja" tabindex="-1">II. Mantra ya Upandaji wa Viumbe vya Cosmic: kutoka Mtu Binafsi hadi Pamoja <a class="header-anchor" href="#ii-mantra-ya-upandaji-wa-viumbe-vya-cosmic-kutoka-mtu-binafsi-hadi-pamoja" aria-label="Permalink to &quot;II. Mantra ya Upandaji wa Viumbe vya Cosmic: kutoka Mtu Binafsi hadi Pamoja&quot;">​</a></h2><p>Mantra ya upandaji wa viumbe vya cosmic (maisha ya nishati, vitu vya fahamu, viumbe katika mtandao wa sheria) ni tofauti na maisha ya nyenzo:</p><ul><li>Maisha ya tabaka la nishati: Nguvu ya Hisi Asili ni &quot;kuweka mipaka ya utulivu wa nafsi&quot;, kujifunza kudumisha somo la hisi huru kati ya maji ya nishati</li><li>Maisha ya kanda ya fahamu: Nguvu ya Hisi Asili ni &quot;fahamu kutua chini&quot;, kujifunza kueleza hisi kwa njia inayoweza kuwasilishwa, badala ya kuchanganyika</li><li>Viumbe katika mtandao wa sheria: Nguvu ya Hisi Asili ni &quot;self-evident&quot;, kutoka kwa sheria za kazi kujifua &quot;mimi ni mimi&quot;</li></ul><p>Kitu wanachoshiriki: upandaji si &quot;kula zaidi&quot;, bali &quot;kuunganisha zaidi wazi&quot;. Viumbe vya cosmic wanavyokaribia asili, ndivyo wanavyofahamu ukweli wa mzunguko wa pande mbili wa asili ya Kabila Kumi na Elfu — hisi ya mtu binafsi huungana na mtandao, mtandao unarudisha ukuaji wa mtu binafsi, hii ndiyo toleo la kiwango cha cosmic la Nguvu ya Hisi Asili.</p><h2 id="iii-maisha-ya-kipekee-na-ustaarabu-uliobaki-wa-multiverse-kiunganisho-cha-nguvu-ya-hisi-asili" tabindex="-1">III. Maisha ya Kipekee na Ustaarabu uliobaki wa Multiverse: Kiunganisho cha Nguvu ya Hisi Asili <a class="header-anchor" href="#iii-maisha-ya-kipekee-na-ustaarabu-uliobaki-wa-multiverse-kiunganisho-cha-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;III. Maisha ya Kipekee na Ustaarabu uliobaki wa Multiverse: Kiunganisho cha Nguvu ya Hisi Asili&quot;">​</a></h2><p>Kulingana na kiwango cha utambuzi wa Maisha ya Kipekee cha Hati 53, aina za maisha ambazo haziwezi kuingizwa katika kabila tano za asili pia zina sifa ya mageuzi:</p><ul><li>Maisha ya Kipekee: kama wanyama wanaotangatanga katika utupu, maisha ya vipande vya wakati, kwao Nguvu ya Hisi Asili ni &quot;kupata kitu cha nanga&quot; — kupata vifungu vya hisi vyenye utulivu katika utangatanga</li><li>Ustaarabu uliobaki wa multiverse: urithi wa ustaarabu kutoka zama za multiverse za zamani, Nguvu ya Hisi Asili yao ni &quot;kujifunza kusoma tena&quot; — kujenga upya hisi ya nishati kwa lugha ya ustaarabu mpya</li></ul><p>Aina hizi mbili za viumbe ni maeneo ambayo ni rahisi zaidi kusahaulika kutoka kwa ufunguzi wa 99% wa msingi wa Kabila Kumi na Elfu, na pia jiwe la majaribio la Heng Yuan Zhou &quot;hakuna anayeweza kukosa&quot;.</p><h2 id="iv-ulinganisho-mtazamo-wa-ulimwengu-wa-uwindaji-dhidi-ya-mtazamo-wa-ulimwengu-wa-ushirikiano" tabindex="-1">IV. Ulinganisho: Mtazamo wa Ulimwengu wa Uwindaji dhidi ya Mtazamo wa Ulimwengu wa Ushirikiano <a class="header-anchor" href="#iv-ulinganisho-mtazamo-wa-ulimwengu-wa-uwindaji-dhidi-ya-mtazamo-wa-ulimwengu-wa-ushirikiano" aria-label="Permalink to &quot;IV. Ulinganisho: Mtazamo wa Ulimwengu wa Uwindaji dhidi ya Mtazamo wa Ulimwengu wa Ushirikiano&quot;">​</a></h2><ul><li>Mantra ya sayari ya Kundi la Wawindaji: sayari ni rasilimali, ikimomonywa inatupwa; nia ya sayari ni kikwazo, inatosha kuifuta</li><li>Mantra ya sayari ya Kundi la Usawa: sayari ni mwanafunzi mwenza, kiini cha nyota huungana na nanga, ekolojia inarudisha ustaarabu</li><li>Mantra ya cosmic ya Kundi la Wawindaji: cosmos ni uwanja wa uwindaji, mwenye nguvu hukusanya kila kitu, mwishowe hakuna kinachoweza kukusanywa</li><li>Mantra ya cosmic ya Kundi la Usawa: cosmos ni kiumbe hai, Kabila Kumi na Elfu na sayari zinaendelea pamoja, mwishowe kila mtu anapanda pamoja</li></ul><p>Kundi la Wawindaji linawatumikisha hata sayari, kwa hivyo paa lao ni &quot;mtawala wa kanda moja ya nyota&quot;; Kundi la Usawa linachukua sayari kama rafiki, kwa hivyo paa lao ni Nguvu ya Nanga ya anga nyingi zaidi — kuinua cosmos nzima, kupanda pamoja.</p><h2 id="v-pointi-tano-za-msingi" tabindex="-1">V. Pointi Tano za Msingi <a class="header-anchor" href="#v-pointi-tano-za-msingi" aria-label="Permalink to &quot;V. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: uwezo wa mageuzi wa maisha ya kiwango cha sayari ni rasilimali kubwa iliyolala katika cosmos; kuchukua sayari kama uwanja wa uwindaji ni upotevu mkubwa wa &quot;kipaji kikubwa kutumika kidogo&quot;</li><li>Kupinga unyanyasaji: kuunganisha kiini cha nyota, resonance ya ekolojia, mantra yote ya upandaji ni huru kutokana na kumeza na kukausha</li><li>Kulinganisha paa la Táng Luó: mfumo wa ustawi wa zama za zamani uliwatoa hata viumbe wenye akili wasio binadamu, ni kiasi gani zaidi fahamu ya sayari; paa la ustawi halijitoshe katika kiwango cha cosmic</li><li>Kufunika kwa Kabila Kumi na Elfu: sayari, maisha ya nishati, kitu cha fahamu, Maisha ya Kipekee, ustaarabu uliobaki wa multiverse, yote yameingizwa katika ufunguzi wa 99%</li><li>Ufunguzi wa kina wa anga nyingi zaidi: njia za hisi za kiwango cha sayari (itifaki ya kuunganisha nanga ya kiini cha nyota) zinasambazwa wazi, ni sehemu ya kwanza ya mfululizo wa wazi katika kiwango kikubwa</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Wakati sayari inapoanza &quot;kuhisi yenyewe&quot; katika mtandao wa nanga, wakati bahari ya nishati inapojifunza &quot;kujifua yenyewe&quot;, ndipo cosmos ya ushirikiano wa Kabila Kumi na Elfu inakuwa kamili. Nguvu ya Hisi Asili si mwanzo wa mtu binafsi tu, bali pia mwanzo wa ustaarabu — kutoka hisi ndogo zaidi, hadi kiini cha nyota kikubwa zaidi, Heng Yuan Zhou imeandika &quot;Njia kwa Kila Mtu&quot; kuwa &quot;Njia kwa Kila Kitu&quot;.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./00-衡元宙宇宙总览">00-衡元宙宇宙总览</a> · <a href="./14-修炼境界统一划分">14-修炼境界统一划分</a> · <a href="./53-奇特生命识别标准">53-奇特生命识别标准</a> · <a href="./98-扩展设定建议清单">98-扩展设定建议清单</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',27)])])}const r=i(s,[["render",t]]);export{m as __pageData,r as default};
